import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { iconPng } from '../pwa/icon';

// The native app icons (app/assets, generated by `npm run icons -w @etagere/app`) are the PWA icon.

const assets = join(__dirname, '..', '..', '..', 'app', 'assets');

describe('native app icons', () => {
  it.each([
    ['icon.png', 1024, 1],
    ['adaptive-icon.png', 1024, 0.72],
    ['splash-icon.png', 512, 1],
  ])('%s is up to date with the icon drawing', (file, size, scale) => {
    expect(readFileSync(join(assets, file)).equals(iconPng(size, scale))).toBe(true);
  });
});

describe('iconPng scale', () => {
  it('draws the same icon at full scale by default', () => {
    expect(iconPng(64, 1).equals(iconPng(64))).toBe(true);
  });

  it('shrinks the drawing around the centre', () => {
    expect(iconPng(64, 0.5).equals(iconPng(64))).toBe(false);
  });

  it.each([0, -1, 1.5, Number.NaN])('refuses the scale %s', (scale) => {
    expect(() => iconPng(64, scale)).toThrow('bad icon scale');
  });
});
